})();
```

`boot` async:
```js
async function boot() {
  var adapter = CA.sites.detect();
  if (!adapter) return;
  state.adapter = adapter;
  state.settings = Object.assign({}, DEFAULTS);
  try { var stored = await api.storage.local.get(DEFAULTS); ... } catch(e) { ... }
  state.overlay = CA.createOverlay();
  state.overlay.mount();
  state.engine = new CA.EngineClient();
  ... handlers ...
  state.engine.connect();
  api.runtime.onMessage.addListener(onRuntimeMessage);
  api.storage.onChanged.addListener(onStorageChanged);
  setInterval(tick, 260);
  setInterval(function(){ if (state.boardEl) state.overlay.setBoard(state.boardEl, state.orientation); }, 500);
  tick();
  render();
}
```
But content script may load before the board; `findBoard` returns null; tick repeats. Good.
- If not a site, return.

`state`:
```js
settings: {...},
adapter, boardEl, orientation:'white',
prev:null, turn:'w', myColor:null,
fen:null, game:null, gameOver:false,
castling: core.newCastlingTracker(), ep:null,
lines:[], bestUci:null, bestMove:null, thinking:false,
engineReady:false, engineSearching:false, error:null,
lastRequestedFen:null, lastAutoFen:null, lastAutoKey:null,
autoBusy:false, autoTimer:null, autoStatus:'', autoStatusTimer:null,
badBoard:null, badReads:0,
clockCandidate:null, clockCount:0,
lastRenderKey:'',
scanCount:0
```

`resolveMyColor(read)`:
```js
if (settings.side === 'w' || settings.side === 'b') return settings.side;
if (!state.myColor) state.myColor = (read.orientation === 'black' ? 'b' : 'w');
return state.myColor;
```
But if side auto and the board element changes (new game), should preserve myColor. Good. If explicit side changes, update.
- In `onSettingsChanged`, if side changes, set `state.myColor = settings.side === 'auto' ? null : settings.side` and reset? If auto and board found, resolve from orientation on next tick. If explicit, use it.

`tick()`:
```js
function tick() {
  if (!state.settings.enabled) { ... return; }
  if (!state.adapter) return;
  var boardEl = state.adapter.findBoard();
  if (!boardEl) { resetBoard(); return; }
  if (boardEl !== state.boardEl) { initBoard(boardEl); }
  var read;
  try { read = state.adapter.read(boardEl); } catch(e) { return; }
  if (!read || !read.board) return;
  state.orientation = read.orientation || state.orientation;
  state.overlay.setBoard(boardEl, state.orientation);
  state.myColor = resolveMyColor(read);
  var board = read.board;

  // same board?
  if (state.prev && core.sameBoard(state.prev.board, board)) {
    state.badReads = 0;
    // clock correction after 2 confirmations
    if (read.clockTurn && state.turn !== read.clockTurn && !state.autoBusy) {
      if (state.clockCandidate === read.clockTurn) state.clockCount++;
      else { state.clockCandidate = read.clockTurn; state.clockCount = 1; }
      if (state.clockCount >= 2) {
        setTurn(read.clockTurn, 'clock');
      }
    } else { state.clockCandidate=null; state.clockCount=0; }
    // keep overlay/HUD updated (my turn may have changed)
    renderThrottled();
    return;
  }

  // changed (or first)
  var inferred = state.prev ? core.inferMove(state.prev.board, board) : null;
  if (state.prev && !inferred) {
    if (!state.badBoard || !core.sameBoard(state.badBoard, board)) {
      state.badBoard = board;
      state.badReads = 1;
      return; // wait for stable frame
    }
    state.badReads++;
    if (state.badReads < 3) return;
  }
  state.badBoard = null;
  state.badReads = 0;

  acceptBoard(read, inferred);
}
```

Wait: `state.badBoard` is a board array; `core.sameBoard` works. But when the board changes again during animation, reset. Good. If the board is stable but ambiguous, after 3 ticks (~750ms) accept. During that time, old arrows remain; okay.
- If `inferred` exists, accept immediately.
- If first read, accept immediately.
- On board change, clear auto timer, autoStatus, lastAuto key.
- `state.prev` is updated in accept.

`acceptBoard(read, inferred)`:
```js
var board = read.board;
var seedTurn = state.prev ? null : state.settings.seedTurn;
var turn = core.detectTurn(state.prev, board, {
  clockTurn: read.clockTurn,
  lastMoveColor: read.lastMoveColor,
  seedTurn: seedTurn || state.settings.seedTurn,
  startTurn: 'w'
});
```
Note `detectTurn` if prev exists and board differs returns inferred other; good. If prev is null → start board w, else clock/lastMoveColor/seed.
- If inferred exists and clockTurn contradicts, prefer inferred (but then validate with chess).
- If no inferred and clockTurn exists, it's already used.
- If start board → w.

Then:
```js
var prevBoard = state.prev ? state.prev.board : null;
var start = core.isStartBoard(board);
if (start) {
  state.castling = core.newCastlingTracker();
  state.ep = null;
  state.gameOver = false;
} else {
  core.updateCastlingTracker(board, state.castling);
  state.ep = inferred ? core.enPassantFromMove(board, inferred) : null;
}
```
Careful: if start is true and we reset castling, then `castlingString` returns all rights. Good.
- If prevBoard exists and board differs, update tracker; if the king moved away and back within one read? Not handled.
- If inferred is a castle, `updateCastlingTracker` sees king not on e1 → marks lost. Good.
- If the opponent's rook on h8 is captured, update tracker marks lost.

Build FEN:
```js
var castling = core.castlingString(board, state.castling);
var fen = core.buildFen(board, turn, {castling: castling, ep: state.ep || '-'});
var game = createGame(fen, board, turn);
