### Background implementation

```js
'use strict';
(function () {
  var core = (globalThis.CA && CA.core) || null;
  var api = globalThis.browser || globalThis.chrome;
  var ports = new Set();
  var worker = null;
  var ready = false;
  var booting = false;
  var current = null;
  var pending = null;
  var lastError = null;
  var infoByMulti = {};
  var infoTimer = null;
  var watchdog = null;
  var bootWatchdog = null;

  function log() { ... }
  function broadcastStatus() { ... }
  function post(port, msg) { try { port.postMessage(msg); } catch {} }

  function ensureWorker() {
    if (worker) return;
    booting = true; ready = false;
    try {
      worker = new Worker(api.runtime.getURL('engine/stockfish.js'));
    } catch (e) { ... }
    worker.onmessage = function(e) { handleRaw(e.data); };
    worker.onerror = function(e) { ... };
    worker.postMessage('uci');
    bootWatchdog = setTimeout(function(){ if (!ready) failWorker('движок не запустился'); }, 25000);
  }

  function resetWorker(reason) {
    ...
    try { worker.terminate(); } catch {}
    worker = null; ready=false; booting=false;
    clearTimeout(watchdog); clearTimeout(bootWatchdog); clearTimeout(infoTimer);
    if (current) { post(current.port, {type:'error', id:current.id, message:reason}); current=null; }
    infoByMulti={};
    broadcastStatus();
  }

  function handleRaw(data) {
    var text = String(data == null ? '' : data);
    var lines = text.split(/\r?\n/);
    for (...) handleLine(line.trim());
  }

  function handleLine(line) {
    if (!line) return;
    if (line === 'uciok') {
      if (bootWatchdog) clearTimeout...
      ready = true; booting = false; lastError = null;
      send('setoption name Hash value 64');
      send('setoption name UCI_ShowWDL value true'); // optional; parse ignores wdl
      send('ucinewgame');
      broadcastStatus();
      startPending();
      return;
    }
    if (line === 'readyok') return;
    if (line.indexOf('info ') === 0) {
      if (!current) return;
      if (line.indexOf(' pv ') < 0 && line.indexOf(' score ') < 0) return;
      var info = core && core.parseInfoLine ? core.parseInfoLine(line) : null;
      if (!info || !info.pv.length) return;
      infoByMulti[info.multipv || 1] = info;
      scheduleInfo();
      return;
    }
    if (line.indexOf('bestmove') === 0) {
      var uci = core && core.parseBestMove ? core.parseBestMove(line) : null;
      var finished = current;
      current = null;
      clearTimeout(watchdog);
      flushInfo(finished);
      if (finished && !finished.cancelled) {
        post(finished.port, {type:'bestmove', id:finished.id, fen:finished.fen, uci: uci || null});
      }
      infoByMulti = {};
      if (pending) { var p = pending; pending=null; start(p); }
      else broadcastStatus();
      return;
    }
    // "info string" ignored; "id" ignored.
  }
```
- `parseInfoLine` returns null for `info string Network...`; good.
- `infoByMulti`: only keep the latest per multipv. Some multipv may disappear (when reducing multiPV); clear at start.
- `scheduleInfo`: if infoTimer exists return; setTimeout 100ms → flushInfo(current), then infoTimer=null.
- `flushInfo(req)`: if !req return; sort by multipv; send `{type:'analysis', id:req.id, fen:req.fen, lines: lines.map(l=>({multipv, depth, seldepth, score, pv, nodes, nps, time}))}`. Limit pv length? Keep all; content uses 10. Could trim to 16 to reduce messages. Do `pv: l.pv.slice(0,16)`.
- Important: don't clear infoByMulti until bestmove; the flush sends.
- After `bestmove`, send final analysis before bestmove to ensure latest lines. `flushInfo(finished)` sends if infoByMulti has content. Then clear.
- If `finished` is cancelled (we stopped due to new request), don't send bestmove; but should we send analysis? no.
- If no `finished` (bestmove after worker reset), ignore.

