/* Shared site adapters: read the position straight from the page DOM. */
(function () {
  'use strict';

  var core = CA.core;
  var sites = {};

  function visible(el) {
    if (!el || !el.isConnected) return false;
    var rect = el.getBoundingClientRect();
    return rect.width >= 120 && rect.height >= 120;
  }

  function isShown(el) {
    if (!el || !el.isConnected) return false;
    var rect = el.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return false;
    var style;
    try { style = getComputedStyle(el); } catch (e) { return true; }
    return style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0';
  }

  function tokens(el) {
    return String(el.className || '').split(/\s+/).filter(Boolean);
  }

  function hasClass(el, name) {
    return !!(el && el.classList && el.classList.contains(name));
  }

  function classText(el) {
    return ' ' + String((el && el.className) || '') + ' ';
  }

  function area(el) {
    var r = el.getBoundingClientRect();
    return r.width * r.height;
  }

  function resultTextGameOver() {
    var selectors = [
      '.round__app .result',
      '.analyse__underboard .result',
      '.game-over-modal',
      '.modal-game-over',
      '[class*="game-over"]',
      '.result'
    ];
    for (var i = 0; i < selectors.length; i++) {
      var nodes = document.querySelectorAll(selectors[i]);
      for (var j = 0; j < nodes.length; j++) {
        var el = nodes[j];
        if (!isShown(el)) continue;
        var text = String(el.textContent || '').trim();
        if (/^(1-0|0-1|½-½|1\/2-1\/2)$/.test(text)) return true;
        if (/game[\s-]*over|победа|поражение|ничья/i.test(text) && text.length < 160) return true;
      }
    }
    return false;
  }

  /* ---------------------------------------------------------------- chess.com */

  var CHESSCOM_LETTER = { p: 'P', n: 'N', b: 'B', r: 'R', q: 'Q', k: 'K' };

  function chesscomPieceFromElement(el) {
    var list = tokens(el);
    var piece = null;
    for (var i = 0; i < list.length; i++) {
      var t = list[i];
      if (t.length === 2 && (t.charAt(0) === 'w' || t.charAt(0) === 'b') && 'pnbrqk'.indexOf(t.charAt(1)) >= 0) {
        piece = t;
        break;
      }
    }
    if (!piece) return null;
    var letter = CHESSCOM_LETTER[piece.charAt(1)];
    return piece.charAt(0) === 'w' ? letter : letter.toLowerCase();
  }

  function chesscomSquareFromElement(el, boardEl, orientation) {
    var list = tokens(el);
    for (var i = 0; i < list.length; i++) {
      var m = /^square-(\d)(\d)$/.exec(list[i]);
      if (m) {
        var file = parseInt(m[1], 10) - 1;
        var rank = parseInt(m[2], 10) - 1;
        if (file >= 0 && file < 8 && rank >= 0 && rank < 8) return rank * 8 + file;
      }
    }
    var data = el.getAttribute('data-square') || el.getAttribute('data-square-id') ||
               el.getAttribute('data-sq');
    if (data) {
      if (/^\d\d$/.test(data)) {
        var f = parseInt(data.charAt(0), 10) - 1;
        var r = parseInt(data.charAt(1), 10) - 1;
        if (f >= 0 && f < 8 && r >= 0 && r < 8) return r * 8 + f;
      }
      var byName = core.squareIndex(data);
      if (byName >= 0) return byName;
    }
    // Newer chess.com builds sometimes position pieces only with CSS. In
    // that case derive the square from the piece centre.
    if (boardEl) {
      var br = boardEl.getBoundingClientRect();
      var pr = el.getBoundingClientRect();
      if (br.width > 40 && br.height > 40 && pr.width > 0 && pr.height > 0) {
        var cell = Math.min(br.width, br.height) / 8;
        var col = Math.round(((pr.left + pr.width / 2) - br.left) / cell - 0.5);
        var row = Math.round(((pr.top + pr.height / 2) - br.top) / cell - 0.5);
        if (col >= 0 && col < 8 && row >= 0 && row < 8) {
          var f2 = orientation === 'black' ? 7 - col : col;
          var r2 = orientation === 'black' ? row : 7 - row;
          return r2 * 8 + f2;
        }
      }
    }
    return -1;
  }

  function chesscomOrientation(boardEl) {
    var flipped = false;
    var el = boardEl;
    for (var depth = 0; el && depth < 4; depth++, el = el.parentElement) {
      if (hasClass(el, 'flipped')) { flipped = true; break; }
      if (el.getAttribute && (el.getAttribute('flipped') !== null ||
          el.getAttribute('data-flipped') === 'true' || el.getAttribute('data-orientation') === 'black')) {
        flipped = true;
        break;
      }
      if (el.getAttribute && el.getAttribute('data-orientation') === 'white') break;
    }
    return flipped ? 'black' : 'white';
  }

  function chesscomClockTurn() {
    var nodes = document.querySelectorAll(
      '.clock-player-turn, .clock-component.clock-player-turn, .clock.clock-player-turn, [class*="clock"][class*="turn"]'
    );
    for (var i = 0; i < nodes.length; i++) {
      var el = nodes[i];
      var cls = classText(el);
      if (cls.indexOf('clock-white') >= 0) return 'w';
      if (cls.indexOf('clock-black') >= 0) return 'b';
      var parent = el.closest ? el.closest('.clock-white, .clock-black') : null;
      if (parent) return hasClass(parent, 'clock-white') ? 'w' : 'b';
      if (hasClass(el, 'clock-white')) return 'w';
      if (hasClass(el, 'clock-black')) return 'b';
    }
    return null;
  }

  function chesscomLastMoveColor(boardEl, board) {
    var marks = boardEl.querySelectorAll('.last-move, [class*="last-move"]');
    if (marks.length < 2) return null;
    var squares = [];
    for (var i = 0; i < marks.length && squares.length < 2; i++) {
      var sq = chesscomSquareFromElement(marks[i], boardEl, chesscomOrientation(boardEl));
      if (sq >= 0 && squares.indexOf(sq) < 0) squares.push(sq);
    }
    if (squares.length !== 2) return null;
    var atA = board[squares[0]];
    var atB = board[squares[1]];
    if (atA && !atB) return core.colorOf(atA);
    if (atB && !atA) return core.colorOf(atB);
    return null;
  }

  function chesscomPieces(boardEl) {
    var pieces = boardEl.querySelectorAll('.piece');
    if (!pieces.length && boardEl.shadowRoot) {
      pieces = boardEl.shadowRoot.querySelectorAll('.piece');
    }
    return pieces;
  }

  var chesscom = {
    id: 'chess.com',
    matches: function (host) { return /(^|\.)chess\.com$/.test(host); },
    findBoard: function () {
      var preferred = document.querySelector('wc-chess-board#board');
      if (visible(preferred)) return preferred;

      var boards = document.querySelectorAll('wc-chess-board');
      var best = null;
      var bestArea = 0;
      for (var i = 0; i < boards.length; i++) {
        var b = boards[i];
        if (!visible(b)) continue;
        var hasPieces = b.querySelector('.piece') || (b.shadowRoot && b.shadowRoot.querySelector('.piece'));
        var a = area(b);
        if (hasPieces && a > bestArea) { best = b; bestArea = a; }
      }
      if (best) return best;

      var fallback = document.querySelector('.board');
      if (visible(fallback) && fallback.querySelector('.piece')) return fallback;
      return best || null;
    },
    read: function (boardEl) {
      var pieces = chesscomPieces(boardEl);
      if (!pieces.length) return null;
      var orientation = chesscomOrientation(boardEl);
      var board = core.emptyBoard();
      var placed = 0;
      for (var i = 0; i < pieces.length; i++) {
        var el = pieces[i];
        var pc = chesscomPieceFromElement(el);
        if (!pc) continue;
        var sq = chesscomSquareFromElement(el, boardEl, orientation);
        if (sq < 0) continue;
        board[sq] = pc;
        placed++;
      }
      if (placed < 2) return null;
      return {
        board: board,
        orientation: orientation,
        clockTurn: chesscomClockTurn(),
        lastMoveColor: chesscomLastMoveColor(boardEl, board),
        gameOver: resultTextGameOver()
      };
    }
  };

  /* ------------------------------------------------------------------ lichess */

  var LICHESS_LETTER = { pawn: 'P', knight: 'N', bishop: 'B', rook: 'R', queen: 'Q', king: 'K' };

  function lichessPieceFromElement(el) {
    var list = tokens(el);
    var color = null;
    var name = null;
    for (var i = 0; i < list.length; i++) {
      if (list[i] === 'white' || list[i] === 'black') color = list[i];
      else if (LICHESS_LETTER[list[i]]) name = list[i];
    }
    if (!color || !name) return null;
    var letter = LICHESS_LETTER[name];
    return color === 'white' ? letter : letter.toLowerCase();
  }

  function translateOf(el) {
    var style = el.getAttribute('style') || '';
    var m = /translate(?:3d)?\(\s*(-?[\d.]+)px\s*,\s*(-?[\d.]+)px/.exec(style);
    if (m) return { x: parseFloat(m[1]), y: parseFloat(m[2]) };
    var t = '';
    try { t = getComputedStyle(el).transform || ''; } catch (e) { t = ''; }
    if (t && t !== 'none') {
      var n = /matrix\(([^)]+)\)/.exec(t);
      if (n) {
        var parts = n[1].split(',').map(function (v) { return parseFloat(v); });
        if (parts.length >= 6) return { x: parts[4], y: parts[5] };
      }
    }
    return { x: 0, y: 0 };
  }

  function lichessOrientation(boardEl) {
    var wrap = boardEl.closest ? boardEl.closest('.cg-wrap') : null;
    if (wrap) {
      if (wrap.classList.contains('orientation-black')) return 'black';
      if (wrap.classList.contains('orientation-white')) return 'white';
    }
    var flipped = boardEl.closest ? boardEl.closest('.orientation-black') : null;
    return flipped ? 'black' : 'white';
  }

  function lichessClockTurn() {
    var active = document.querySelectorAll('.rclock.running, .rclock.rclock-turn, .rclock-turn');
    for (var i = 0; i < active.length; i++) {
      var el = active[i];
      if (hasClass(el, 'rclock-white') || hasClass(el, 'clock-white')) return 'w';
      if (hasClass(el, 'rclock-black') || hasClass(el, 'clock-black')) return 'b';
      var parent = el.closest ? el.closest('.rclock-white, .rclock-black, .clock-white, .clock-black') : null;
      if (parent) {
        return hasClass(parent, 'rclock-white') || hasClass(parent, 'clock-white') ? 'w' : 'b';
      }
    }
    return null;
  }

  function lichessLastMove(boardEl, orientation, rect) {
    var marks = boardEl.querySelectorAll('square.last-move, .last-move');
    if (marks.length < 2) return null;
    var cell = Math.min(rect.width, rect.height) / 8;
    if (!cell) return null;
    var squares = [];
    for (var i = 0; i < marks.length && squares.length < 2; i++) {
      var tr = translateOf(marks[i]);
      var col = Math.round(tr.x / cell);
      var row = Math.round(tr.y / cell);
      if (col < 0 || col > 7 || row < 0 || row > 7) continue;
      var file = orientation === 'white' ? col : 7 - col;
      var rank = orientation === 'white' ? 7 - row : row;
      var sq = rank * 8 + file;
      if (squares.indexOf(sq) < 0) squares.push(sq);
    }
    if (squares.length !== 2) return null;
    return { a: squares[0], b: squares[1] };
  }

  function lichessPieces(boardEl) {
    var all = boardEl.querySelectorAll('piece');
    var out = [];
    for (var i = 0; i < all.length; i++) {
      if (all[i].parentElement === boardEl) out.push(all[i]);
    }
    return out;
  }

  var lichess = {
    id: 'lichess',
    matches: function (host) { return host === 'lichess.org' || /\.lichess\.org$/.test(host); },
    findBoard: function () {
      var boards = document.querySelectorAll('cg-board');
      var best = null;
      var bestArea = 0;
      for (var i = 0; i < boards.length; i++) {
        var b = boards[i];
        if (!visible(b)) continue;
        var hasPieces = b.querySelector('piece');
        var a = area(b);
        if (hasPieces && a > bestArea) { best = b; bestArea = a; }
      }
      if (best) return best;
      for (var j = 0; j < boards.length; j++) {
        if (visible(boards[j])) return boards[j];
      }
      return null;
    },
    read: function (boardEl) {
      var pieces = lichessPieces(boardEl);
      if (!pieces.length) return null;
      var rect = boardEl.getBoundingClientRect();
      var cell = Math.min(rect.width, rect.height) / 8;
      if (!cell) return null;
      var orientation = lichessOrientation(boardEl);
      var board = core.emptyBoard();
      var placed = 0;
      for (var i = 0; i < pieces.length; i++) {
        var el = pieces[i];
        var pc = lichessPieceFromElement(el);
        if (!pc) continue;
        var tr = translateOf(el);
        var col = Math.round(tr.x / cell);
        var row = Math.round(tr.y / cell);
        if (col < 0 || col > 7 || row < 0 || row > 7) continue;
        var file = orientation === 'white' ? col : 7 - col;
        var rank = orientation === 'white' ? 7 - row : row;
        board[rank * 8 + file] = pc;
        placed++;
      }
      if (placed < 2) return null;

      var lastMoveColor = null;
      var last = lichessLastMove(boardEl, orientation, rect);
      if (last) {
        // The square that still holds a piece is the destination of the last move.
        var atA = board[last.a];
        var atB = board[last.b];
        if (atA && !atB) lastMoveColor = core.colorOf(atA);
        else if (atB && !atA) lastMoveColor = core.colorOf(atB);
      }

      return {
        board: board,
        orientation: orientation,
        clockTurn: lichessClockTurn(),
        lastMoveColor: lastMoveColor,
        gameOver: resultTextGameOver()
      };
    }
  };

  sites.chesscom = chesscom;
  sites.lichess = lichess;
  sites.list = [chesscom, lichess];
  sites.detect = function () {
    var host = location.hostname;
    for (var i = 0; i < sites.list.length; i++) {
      if (sites.list[i].matches(host)) return sites.list[i];
    }
    return null;
  };

  CA.sites = sites;
})();

