- The overlay's `setBoard` calls scheduleSync internally. Good.

`init`:
```js
(function () {
  'use strict';
  if (window.top !== window) return;
  if (!globalThis.CA || !CA.core) return;
  var core = CA.core;
  var api = globalThis.browser || globalThis.chrome;
  var ChessCtor = globalThis.Chess;
