- `globalThis` supported in Firefox. Yes.
- Content scripts may run before the vendor script? Manifest order ensures. Good.
- If `CA.sites` missing, return.
- `init` async. If storage fails, use defaults.

- Engine client connect triggers background worker boot. If no board (e.g., a chess.com page without a game), the engine still boots. That's okay but wasted. Could connect lazily on first analysis. The HUD would show launching only after a board is found; the engine status would be false until connect. Better: connect when a board is found, not on init. In `tick`, after finding a board, if `!state.engineConnected` → `state.engine.connect()`. This avoids loading the engine on non-game pages (lichess homepage, chess.com lessons). The content script matches all pages on those hosts, including home pages. The engine is 1.8MB; don't load until a board exists.
  - `EngineClient.connect()` can be called from `initBoard`. Set `state.engineConnected=true` after. If the port disconnects, the client reconnects automatically; fine.
  - `init` should set up engine events but not connect.
  - `onBest`/analysis only after board.
  - The popup engine status before a board is found: background worker may not be started; popup shows "движок не запущен" or ready false. Fine.
- If the engine client connects on `initBoard`, and initBoard is called before `state.engine` exists? init sets engine before starting tick. Good.
- If the board is lost, keep the engine connected; it might be reused. Fine.
- If the user navigates to a non-game page via SPA but the same content script, the engine stays; okay.

- `state.engineReady` initial false; the overlay hides until a board. After connecting, background sends status. Good.

- `init` sets up `api.storage.onChanged`; if `api` missing, return.
- Start `setInterval(tick, 250)` and `tick()` after a short delay? `document_idle` ensures DOM. Call `setTimeout(tick, 0)`. Fine.
- `setInterval` keeps running; if the extension context is invalidated (add-on reload), `api` calls throw. Catch in tick? Reading storage not in tick. `adapter.findBoard` works; engine calls throw/caught. The interval continues but harmless. Could add a try/catch around tick and stop after many errors. Not necessary.

- `state.settings.enabled` check at the top of tick; if false, hide overlay once and return. Use `state.wasEnabled` to avoid repeated hide:
```js
if (!state.settings.enabled) {
  if (state.wasEnabled !== false) { state.overlay.hide(); state.wasEnabled=false; }
  return;
}
state.wasEnabled = true;
```
- On disable, also stop the engine via storage handler.

- `tick` calls `render()` on every same-board clock correction? No; only when orientation changes/gameOver. Good.
- On each new analysis message, render.

- The overlay `update` sets `state = next` and renderHud; it also calls scheduleSync. Good.
- The overlay's HUD `refs.engine` hardcoded "Stockfish 19"; fine.

- One bug in overlay: `update` is reassigned after `mount`? The returned `update` points to the overwritten function. Inside `createOverlay`, `var baseUpdate = update; update = function(next) {...}`. `baseUpdate` unused. Fine.
- `renderHud` references `refs.turn` etc., which exist after mount. `update` may be called before mount? init mounts first. Fine.

- `hide()` hides canvas/hud but doesn't reset `boardEl`. When re-enabled, `setBoard` shows. Good.

Let's write content.js.

input.content:
/*
 * Chess Assist controller. Reads the site board, keeps a FEN, asks the
 * background Stockfish worker for analysis and (optionally) plays the move.
 */
(function () {
  'use strict';

  if (window.top !== window) return;
  if (!globalThis.CA || !CA.core || !CA.sites) return;

  var core = CA.core;
  var api = globalThis.browser || globalThis.chrome;
  var ChessCtor = globalThis.Chess;

  var DEFAULTS = {
    enabled: true,
    side: 'auto',            // 'auto' | 'w' | 'b'
    seedTurn: 'w',           // whose move it is when the extension first reads a position
    showArrow: true,
    showHud: true,
    autoPlay: false,
    autoPlayDelayMs: 700,
    multiPV: 1,
    movetimeMs: 1200
  };

  var state = {
    settings: Object.assign({}, DEFAULTS),
    adapter: null,
    boardEl: null,
    orientation: 'white',
    myColor: null,
    myColorResolved: false,
    overlay: null,
    engine: null,
    autoMover: null,
    prev: null,
    turn: 'w',
    fen: null,
    game: null,
    gameOver: false,
    castling: core.newCastlingTracker(),
    ep: null,
    lines: [],
    bestUci: null,
    bestMove: null,
    bestSan: '',
    scoreText: '',
    depth: null,
    thinking: false,
    engineReady: false,
    engineError: null,
    error: null,
    clockTurn: null,
    clockDisagreement: 0,
    lastRequestedFen: null,
    lastAutoFen: null,
    lastAutoKey: null,
    autoTimer: null,
    autoKey: null,
    autoBusy: false,
    autoStatus: '',
    badReads: 0,
    pendingBoard: null,
    pendingSince: 0,
    wasEnabled: true
  };

  function clampInt(value, lo, hi) {
    var n = parseInt(value, 10);
    if (!isFinite(n)) n = lo;
    return Math.max(lo, Math.min(hi, n));
  }

  function loadGame(fen) {
    if (typeof ChessCtor !== 'function') return null;
    try { return new ChessCtor(fen); } catch (e) { return null; }
  }

  function buildFenFor(board, turn, ep, castlingStr) {
    var castling = castlingStr != null ? castlingStr : core.castlingString(board, state.castling);
    var epValue = ep != null ? ep : (state.ep || '-');
    var fen = core.buildFen(board, turn, { castling: castling, ep: epValue });
    var game = loadGame(fen);
    if (!game && typeof ChessCtor === 'function') {
      var alt = core.buildFen(board, turn, { castling: '-', ep: '-' });
      game = loadGame(alt);
      if (!game) return null;
      fen = alt;
    }
    return { fen: fen, game: game };
  }

  function validateTurn(board, turn, game) {
    if (!game) return turn;
    var opp = core.otherColor(turn);
    var kingSq = core.findKing(board, opp);
    if (kingSq < 0) return turn;
    var attacked = false;
    try { attacked = game.isAttacked(core.squareName(kingSq), turn); } catch (e) { attacked = false; }
    return attacked ? opp : turn;
  }

  function isGameOver(game) {
    if (!game) return false;
    try { return !!game.isGameOver(); } catch (e) { return false; }
  }

  function resolveMyColor() {
    if (state.settings.side === 'w' || state.settings.side === 'b') {
      state.myColor = state.settings.side;
      state.myColorResolved = true;
      return;
    }
    if (!state.boardEl) {
      state.myColor = null;
      state.myColorResolved = false;
      return;
    }
    state.myColor = state.orientation === 'black' ? 'b' : 'w';
    state.myColorResolved = true;
  }

  function clearAnalysis() {
    state.lines = [];
    state.bestUci = null;
    state.bestMove = null;
    state.bestSan = '';
    state.scoreText = '';
    state.depth = null;
    state.thinking = false;
    state.lastRequestedFen = null;
    state.lastAutoFen = null;
    state.lastAutoKey = null;
    state.autoKey = null;
    state.autoStatus = '';
    if (state.autoTimer) {
      clearTimeout(state.autoTimer);
      state.autoTimer = null;
    }
  }

  function requestAnalysis() {
    if (!state.engine || !state.fen || state.gameOver || !state.settings.enabled) return;
    if (state.fen === state.lastRequestedFen) return;
    state.lastRequestedFen = state.fen;
    state.thinking = true;
    state.error = null;
    state.engine.analyze({
      fen: state.fen,
      multiPV: clampInt(state.settings.multiPV, 1, 3),
      movetime: clampInt(state.settings.movetimeMs, 300, 5000)
    });
    render();
  }

  function render() {
    if (!state.overlay) return;
    if (!state.boardEl || !state.adapter) {
      state.overlay.hide();
      return;
    }
    state.overlay.setBoard(state.boardEl, state.orientation);
    var primary = state.lines[0] || null;
    state.overlay.update({
      showArrow: !!state.settings.showArrow,
      showHud: !!state.settings.showHud,
      lines: state.settings.showArrow ? state.lines : [],
      turn: state.turn,
      myTurn: !!state.myColor && state.turn === state.myColor,
      bestUci: state.bestUci,
      scoreText: state.scoreText || (primary ? primary.scoreText : ''),
      san: state.bestSan || (primary ? primary.firstSan : ''),
      depth: state.depth || (primary ? primary.depth : null),
      thinking: !!state.thinking,
      engineReady: !!state.engineReady,
      gameOver: !!state.gameOver,
      autoPlay: !!state.settings.autoPlay,
      autoStatus: state.autoStatus,
      error: state.error || state.engineError || null,
      site: state.adapter.id
    });
  }

  function publicState() {
    return {
      ok: true,
      site: state.adapter ? state.adapter.id : null,
      boardFound: !!state.boardEl,
      enabled: !!state.settings.enabled,
      fen: state.fen,
      turn: state.turn,
      turnText: state.turn === 'w' ? 'белые' : 'чёрные',
      myColor: state.myColor,
      myTurn: !!state.myColor && state.turn === state.myColor,
      thinking: !!state.thinking,
      engineReady: !!state.engineReady,
      depth: state.depth,
      score: state.scoreText,
      bestSan: state.bestSan,
      lines: state.lines.slice(0, 3).map(function (line) {
        return {
          san: line.san,
          firstSan: line.firstSan,
          score: line.scoreText,
          depth: line.depth,
          multipv: line.multipv
        };
      }),
      autoPlay: !!state.settings.autoPlay,
      autoBusy: !!state.autoBusy,
      autoStatus: state.autoStatus,
      gameOver: !!state.gameOver,
      error: state.error || state.engineError || null
    };
  }

  function isLegalMove(fen, move) {
    if (typeof ChessCtor !== 'function') return true;
    try {
      var game = new ChessCtor(fen);
      var result = game.move({
        from: core.squareName(move.from),
        to: core.squareName(move.to),
        promotion: move.promotion || undefined
      });
      return !!result;
    } catch (e) {
      return false;
    }
  }

  function waitForBoardChange(previousBoard, timeoutMs) {
    return new Promise(function (resolve) {
      var started = Date.now();
      function check() {
        if (!state.boardEl || !state.adapter) { resolve(false); return; }
        var read = null;
        try { read = state.adapter.read(state.boardEl); } catch (e) { read = null; }
        if (read && read.board && !core.sameBoard(read.board, previousBoard)) {
          resolve(true);
          return;
        }
        if (Date.now() - started >= timeoutMs) { resolve(false); return; }
        setTimeout(check, 90);
      }
      check();
    });
