function lichessClockTurn(orientation) {
  var active = document.querySelectorAll('.rclock.running, .rclock.rclock-turn, .rclock-turn');
  for (var i = 0; i < active.length; i++) {
    var el = active[i];
    if (!isShown(el)) continue;
    if (hasClass(el, 'rclock-white') || hasClass(el, 'clock-white')) return 'w';
    if (hasClass(el, 'rclock-black') || hasClass(el, 'clock-black')) return 'b';
    var parent = el.closest ? el.closest('.rclock-white, .rclock-black, .clock-white, .clock-black') : null;
    if (parent) {
      return hasClass(parent, 'rclock-white') || hasClass(parent, 'clock-white') ? 'w' : 'b';
    }
    // Lichess often marks the running clock only with rclock-top /
    // rclock-bottom; the orientation tells us which colour that is.
    if (hasClass(el, 'rclock-top') || hasClass(el, 'rclock-bottom')) {
      var bottom = orientation === 'black' ? 'b' : 'w';
      return hasClass(el, 'rclock-top') ? core.otherColor(bottom) : bottom;
    }
  }
  return null;
}

