    var wrap = document.querySelector('.cg-wrap');
    var board = document.querySelector('cg-board');
    var cell = board.getBoundingClientRect().width / 8;
    Array.prototype.forEach.call(board.querySelectorAll(':scope > piece'), function(p){
      var m = /translate\((-?[\d.]+)px,\s*(-?[\d.]+)px\)/.exec(p.getAttribute('style'));
      if (!m) return;
      var col = Math.round(parseFloat(m[1]) / cell);
      var row = Math.round(parseFloat(m[2]) / cell);
      p.style.transform = 'translate(' + (7 - col) * cell + 'px, ' + (7 - row) * cell + 'px)';
    });
