      var col = orientation === 'white' ? f : 7 - f;
      var row = orientation === 'white' ? 7 - r : r;
      ctx.fillStyle = color.fill;
      roundRect(col * cell + cell * 0.04, row * cell + cell * 0.04, cell * 0.92, cell * 0.92, cell * 0.12);
      ctx.fill();

      f = core.fileOf(move.to);
      r = core.rankOf(move.to);
      col = orientation === 'white' ? f : 7 - f;
      row = orientation === 'white' ? 7 - r : r;
      ctx.fillStyle = color.fill;
      roundRect(col * cell + cell * 0.04, row * cell + cell * 0.04, cell * 0.92, cell * 0.92, cell * 0.12);
      ctx.fill();

      var dx = b.x - a.x;
      var dy = b.y - a.y;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (len < cell * 0.4) return;
      var ux = dx / len;
      var uy = dy / len;

      var startPad = cell * 0.24;
      var endPad = cell * 0.18;
      var sx = a.x + ux * startPad;
      var sy = a.y + uy * startPad;
      var ex = b.x - ux * endPad;
      var ey = b.y - uy * endPad;
      var headLen = Math.min(cell * 0.40, len * 0.42);
      var headHalf = Math.min(cell * 0.23, len * 0.22);
      var baseX = ex - ux * headLen;
      var baseY = ey - uy * headLen;

      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

