      ctx.moveTo(sx, sy);
      ctx.lineTo(baseX, baseY);
      ctx.strokeStyle = 'rgba(10, 12, 16, 0.45)';
      ctx.lineWidth = cell * 0.155;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(sx, sy);
      ctx.lineTo(baseX, baseY);
      ctx.strokeStyle = color.line;
      ctx.lineWidth = cell * 0.105;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(ex, ey);
      ctx.lineTo(baseX + uy * headHalf, baseY - ux * headHalf);
      ctx.lineTo(baseX - uy * headHalf, baseY + ux * headHalf);
      ctx.closePath();
      ctx.fillStyle = color.line;
      ctx.fill();
      ctx.strokeStyle = 'rgba(10, 12, 16, 0.40)';
      ctx.lineWidth = Math.max(1, cell * 0.025);
