        tone = 'ok';
      } else {
        status = '\u0445\u043e\u0434 \u0441\u043e\u043f\u0435\u0440\u043d\u0438\u043a\u0430 \u2014 \u043f\u0440\u043e\u0433\u043d\u043e\u0437';
