/*
 * Auto-move driver. Sites accept only user input, so we replay the same
 * click / drag event sequences a mouse produces. Some sites may still reject
 * synthetic events; the controller verifies every move and reports failure.
 */
(function () {
  'use strict';

  var core = CA.core;

  function sleep(ms) {
    return new Promise(function (resolve) { setTimeout(resolve, ms); });
  }

  function isShown(el) {
    if (!el || !el.isConnected) return false;
    var r = el.getBoundingClientRect();
    if (r.width <= 0 || r.height <= 0) return false;
    var s;
    try { s = getComputedStyle(el); } catch (e) { return true; }
    return s.display !== 'none' && s.visibility !== 'hidden' && s.opacity !== '0';
  }

  function fire(target, type, x, y, buttons) {
    if (!target) return;
    var init = {
      bubbles: true,
      cancelable: true,
      composed: true,
      view: window,
      clientX: x,
      clientY: y,
      screenX: x + (window.screenX || 0),
      screenY: y + (window.screenY || 0),
      button: 0,
      buttons: buttons || 0,
      detail: type === 'click' ? 1 : 0
    };
    var event = null;
    try {
      if (type.indexOf('pointer') === 0 && typeof PointerEvent === 'function') {
        init.pointerId = 1;
        init.pointerType = 'mouse';
        init.isPrimary = true;
        init.width = 1;
        init.height = 1;
        init.pressure = buttons ? 0.5 : 0;
        event = new PointerEvent(type, init);
      } else {
        event = new MouseEvent(type, init);
      }
    } catch (e) {
      try { event = new MouseEvent(type, init); } catch (e2) { return; }
    }
    try { target.dispatchEvent(event); } catch (e3) { /* ignore */ }
