(function(){
    var board = document.querySelector('cg-board');
    var rect = board.getBoundingClientRect();
    var cell = Math.min(rect.width, rect.height) / 8;
    var pawn = null;
    Array.prototype.forEach.call(board.querySelectorAll(':scope > piece'), function(p){
      var m = /translate\((-?[\d.]+)px,\s*(-?[\d.]+)px\)/.exec(p.getAttribute('style'));
      if (!m) return;
      if (Math.abs(parseFloat(m[1]) - 4 * cell) < 2 && Math.abs(parseFloat(m[2]) - 6 * cell) < 2) pawn = p;
    });
    if (!pawn) return { ok: false, reason: 'e2 pawn not found' };
    pawn.style.transform = 'translate(' + 4 * cell + 'px, ' + 4 * cell + 'px)';
    var old = document.getElementById('ca-last-move-mock');
    if (old) old.remove();
    var wrap = document.createElement('div');
    wrap.id = 'ca-last-move-mock';
    wrap.style.cssText = 'position:absolute;left:0;top:0;width:0;height:0';
