function lichessPieces(boardEl) {
  var all = boardEl.querySelectorAll('piece');
  var out = [];
  for (var i = 0; i < all.length; i++) {
    // A premove preview sits on the destination square but the position has
    // not changed yet. Ignore it; the real piece is still on its origin.
    if (all[i].parentElement === boardEl && !hasClass(all[i], 'premove')) out.push(all[i]);
  }
  return out;
}

